// Base do backend. Constante, nunca $env: no worker do n8n a expressao
// lanca 'access to env vars denied' e o no morre calado.
const API_BASE = 'https://agenda-magnetica-painel.vercel.app';
const EVOLUTION_BASE = 'https://evo.fixwear.com.br';
return [{ json: { api_base: API_BASE.replace(/\/$/, ''), evolution_base: EVOLUTION_BASE.replace(/\/$/, '') } }];

// Monta uma mensagem de lembrete por consulta e a pendencia que o "confirmo"
// do cliente vai fechar. Nada aqui passa por modelo: o texto e deterministico,
// e a IA so entra quando o cliente responde.
//
// O relogio nao tem conversa, entao cada item carrega a propria instancia e o
// proprio contato. Nenhuma chave e derivada de outro item.

const OFFSET_MIN = -180; // America/Sao_Paulo, sem horario de verao desde 2019
const DIAS = ['domingo', 'segunda-feira', 'terca-feira', 'quarta-feira',
  'quinta-feira', 'sexta-feira', 'sabado'];
// A pendencia precisa sobreviver da vespera ate a hora da consulta. am:estado
// (6 h) nao serve de memoria aqui, e e por isso que a pendencia do lembrete
// carrega `origem` e e isenta da guarda de "o ultimo turno falou dela".
const FOLGA_APOS_INICIO_MIN = 30;

const envelope = $('buscar lembretes').first().json || {};
const lembretes = (envelope.ok && envelope.data && Array.isArray(envelope.data.lembretes))
  ? envelope.data.lembretes
  : [];

function texto(valor) {
  return String(valor === null || valor === undefined ? '' : valor).trim();
}

function primeiroNome(nome) {
  const limpo = texto(nome).split(/\s+/)[0] || '';
  if (limpo.length < 2 || /\d/.test(limpo)) return '';
  return limpo.charAt(0).toUpperCase() + limpo.slice(1).toLowerCase();
}

function quando(iso) {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return null;
  const local = new Date(d.getTime() + OFFSET_MIN * 60000);
  const dois = (n) => String(n).padStart(2, '0');
  return {
    dia: DIAS[local.getUTCDay()],
    data: `${dois(local.getUTCDate())}/${dois(local.getUTCMonth() + 1)}`,
    hora: `${dois(local.getUTCHours())}h${local.getUTCMinutes() ? dois(local.getUTCMinutes()) : ''}`,
  };
}

const itens = [];

for (const lembrete of lembretes) {
  const telefone = texto(lembrete.telefone).replace(/\D/g, '');
  const instancia = texto(lembrete.instance_name);
  const inicio = texto(lembrete.inicio);
  const idConsulta = Number(lembrete.id_consulta);
  const momento = quando(inicio);
  // Sem qualquer uma destas quatro coisas nao ha lembrete possivel. A consulta
  // ja ficou marcada como enviada na API, e assim fica: reenviar na proxima
  // passada nao resolveria um cadastro incompleto.
  if (!telefone || !instancia || !idConsulta || !momento) continue;

  const nome = primeiroNome(lembrete.cliente_nome);
  const saudacao = nome ? `Oi, ${nome}!` : 'Oi!';
  const servico = texto(lembrete.servico);
  const profissional = texto(lembrete.profissional);
  const comQuem = profissional ? ` com ${profissional}` : '';
  const oQue = servico ? `${servico}${comQuem}` : `seu atendimento${comQuem}`;

  // O painel promete cinco variaveis ao dono. Se elas nao forem trocadas aqui, o
  // cliente recebe "{nome}" com chaves e tudo. Todos os valores sao nossos e
  // deterministicos - nenhum vem de modelo.
  const VARIAVEIS = {
    nome: nome || 'tudo bem',
    data: `${momento.dia}, dia ${momento.data}`,
    horario: momento.hora,
    profissional: profissional,
    procedimento: servico,
  };
  function preencher(modelo) {
    return modelo.replace(/\{(nome|data|horario|profissional|procedimento)\}/g,
      (_todo, chave) => VARIAVEIS[chave] || '');
  }

  const modelo = texto(lembrete.mensagem);
  const temVariavel = /\{(nome|data|horario|profissional|procedimento)\}/.test(modelo);
  // Com variavel, o texto do dono E a mensagem. Sem variavel, ele vira abertura
  // e o horario continua vindo daqui - senao um lembrete anunciaria uma coisa e
  // a pendencia confirmaria outra.
  const padrao = `${saudacao} Passando para confirmar ${oQue} `
    + `${momento.dia}, dia ${momento.data}, as ${momento.hora}.`;
  const corpo = temVariavel
    ? preencher(modelo)
    : (modelo ? `${modelo}\n\n${padrao}` : padrao);

  // A pergunta e sempre nossa, mesmo quando o dono escreveu a mensagem inteira:
  // e ela que diz ao cliente o que responder para fechar a pendencia.
  const partes = [corpo,
    'Voce confirma? Responda *sim* para confirmar, ou me diga se precisar remarcar.'];

  // `expira_em` vai um pouco alem do inicio: quem responde "sim" cinco minutos
  // antes da consulta ainda esta confirmando presenca, nao reabrindo agenda.
  const expira = new Date(new Date(inicio).getTime() + FOLGA_APOS_INICIO_MIN * 60000);

  itens.push({
    json: {
      instance: instancia,
      remote_jid: `${telefone}@s.whatsapp.net`,
      texto: partes.join('\n\n'),
      pendente: {
        tipo: 'confirmar',
        // Marca que esta pendencia nasceu FORA da conversa. `resolver e decidir`
        // usa isso para nao descarta-la quando am:estado ja expirou.
        origem: 'lembrete',
        consulta_id: idConsulta,
        inicio,
        acao_id: `lembrete-${idConsulta}`,
        expira_em: expira.toISOString(),
      },
      // TTL da chave: ate a consulta comecar, mais a folga. Nunca menos que um
      // minuto, senao a chave morreria antes de a mensagem chegar.
      ttl_pendente: Math.max(60, Math.round((expira.getTime() - Date.now()) / 1000)),
    },
  });
}

return itens;
